async def _drain() -> None:
    """Cancel all tasks and wait for their cleanup to finish.

    This must complete even if the awaiting frame is itself being
    cancelled, so we retry the wait, re-cancelling on each cancellation,
    until every task has actually finished running its cleanup code.
    """
    for fut in running:
        fut.cancel()
    while True:
        try:
            await gathered
            return
        except asyncio.CancelledError:
            # Outer cancellation tried to abort our cleanup wait. Re-issue
            # cancellation and keep waiting until tasks truly finish.
            for fut in running:
                if not fut.done():
                    fut.cancel()
            if all(fut.done() for fut in running):
                return

